--keel:notx
-- Rollup detention_customer_monthly of detention_occurrences, generated by keel's analytics/rollup. Do not edit; change the declaration and generate again.
CREATE TABLE IF NOT EXISTS keel_rollup_dirty (
    rollup text COLLATE "C" NOT NULL,
    tenant_key text COLLATE "C" NOT NULL,
    bucket timestamptz NOT NULL,
    xid xid8 NOT NULL,
    marked_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (rollup, tenant_key, bucket, xid)
);
CREATE INDEX IF NOT EXISTS keel_rollup_dirty_marked ON keel_rollup_dirty (marked_at);
CREATE TABLE IF NOT EXISTS keel_rollup_state (
    rollup text COLLATE "C" PRIMARY KEY,
    ready_at timestamptz NOT NULL
);
DELETE FROM keel_rollup_state WHERE rollup = 'detention_customer_monthly';
DELETE FROM keel_rollup_dirty WHERE rollup = 'detention_customer_monthly';
DO $keel$
BEGIN
    IF EXISTS (SELECT 1 FROM pg_class WHERE oid = to_regclass('"detention_customer_monthly"') AND obj_description(oid, 'pg_class') = 'keel rollup detention_customer_monthly of detention_occurrences') THEN
        DROP TABLE "detention_customer_monthly";
    END IF;
END
$keel$;
CREATE TABLE "detention_customer_monthly" AS SELECT s."business_unit_id" AS "business_unit_id", s."organization_id" AS "organization_id", date_trunc('month', to_timestamp(s."clock_start_at"), (coalesce((SELECT z."timezone" FROM "organizations" z WHERE z."id" = s."organization_id"), 'UTC'))) AS "bucket", s."customer_id" AS "customer_id", count(*) AS "row_count", count(*) FILTER (WHERE CAST(greatest((s."raw_dwell_minutes" - s."free_minutes_granted"), 0::integer) AS bigint) > 0) AS "detained_stops", sum(CAST(greatest((s."raw_dwell_minutes" - s."free_minutes_granted"), 0::integer) AS bigint)) AS "past_free_minutes", sum(CAST(greatest((s."raw_dwell_minutes" - s."free_minutes_granted"), 0::integer) AS bigint)) FILTER (WHERE (NOT (s."arrived_late" IS TRUE) AND NOT (s."schedule_type" = 'Open') AND NOT ((s."appointment_start" IS NOT NULL AND s."arrived_at" IS NOT NULL AND s."arrived_at" < s."appointment_start")))) AS "dock_minutes", sum(CAST(greatest((s."raw_dwell_minutes" - s."free_minutes_granted"), 0::integer) AS bigint)) FILTER (WHERE (NOT (s."arrived_late" IS TRUE) AND s."schedule_type" = 'Open')) AS "open_minutes", sum(CAST(greatest((s."raw_dwell_minutes" - s."free_minutes_granted"), 0::integer) AS bigint)) FILTER (WHERE (NOT (s."arrived_late" IS TRUE) AND NOT (s."schedule_type" = 'Open') AND (s."appointment_start" IS NOT NULL AND s."arrived_at" IS NOT NULL AND s."arrived_at" < s."appointment_start"))) AS "early_minutes", sum(CAST(greatest((s."raw_dwell_minutes" - s."free_minutes_granted"), 0::integer) AS bigint)) FILTER (WHERE s."arrived_late" IS TRUE) AS "late_minutes", sum(s."raw_dwell_minutes") AS "dwell_minutes", sum(s."billable_amount") AS "billable_amount", sum(s."driver_pay_amount") AS "driver_pay_amount", sum(s."net_margin") AS "net_margin", sum(s."waived_amount") AS "waived_amount", count(*) FILTER (WHERE s."status" = 'Disputed') AS "disputed_stops", count(*) FILTER (WHERE s."suppressed_by_gate" IS TRUE) AS "suppressed_stops", count(*) FILTER (WHERE s."notice_deadline_at" IS NOT NULL) AS "notices_due", count(*) FILTER (WHERE (s."notice_deadline_at" IS NOT NULL AND s."notice_sent_at" IS NOT NULL AND s."notice_sent_at" <= s."notice_deadline_at")) AS "notices_on_time" FROM "detention_occurrences" s GROUP BY 1, 2, 3, 4 WITH NO DATA;
COMMENT ON TABLE "detention_customer_monthly" IS 'keel rollup detention_customer_monthly of detention_occurrences';
ALTER TABLE "detention_customer_monthly" ALTER COLUMN "business_unit_id" SET NOT NULL, ALTER COLUMN "organization_id" SET NOT NULL;
CREATE UNIQUE INDEX "detention_customer_monthly_key" ON "detention_customer_monthly" ("business_unit_id", "organization_id", "bucket", "customer_id") NULLS NOT DISTINCT;
CREATE OR REPLACE FUNCTION keel_rollup_detention_customer_monthly() RETURNS trigger LANGUAGE plpgsql AS $keel$
BEGIN
    IF TG_OP = 'INSERT' THEN
        INSERT INTO keel_rollup_dirty (rollup, tenant_key, bucket, xid)
        SELECT DISTINCT 'detention_customer_monthly', replace(replace(coalesce(n."business_unit_id"::text, ''), '\', '\\'), '/', '\/') || '/' || replace(replace(coalesce(n."organization_id"::text, ''), '\', '\\'), '/', '\/'), coalesce(date_trunc('month', to_timestamp(n."clock_start_at"), (coalesce((SELECT z."timezone" FROM "organizations" z WHERE z."id" = n."organization_id"), 'UTC'))), 'infinity'), pg_current_xact_id()
          FROM keel_new n
        ON CONFLICT DO NOTHING;
    ELSIF TG_OP = 'DELETE' THEN
        INSERT INTO keel_rollup_dirty (rollup, tenant_key, bucket, xid)
        SELECT DISTINCT 'detention_customer_monthly', replace(replace(coalesce(n."business_unit_id"::text, ''), '\', '\\'), '/', '\/') || '/' || replace(replace(coalesce(n."organization_id"::text, ''), '\', '\\'), '/', '\/'), coalesce(date_trunc('month', to_timestamp(n."clock_start_at"), (coalesce((SELECT z."timezone" FROM "organizations" z WHERE z."id" = n."organization_id"), 'UTC'))), 'infinity'), pg_current_xact_id()
          FROM keel_old n
        ON CONFLICT DO NOTHING;
    ELSE
        INSERT INTO keel_rollup_dirty (rollup, tenant_key, bucket, xid)
        SELECT DISTINCT 'detention_customer_monthly', replace(replace(coalesce(n."business_unit_id"::text, ''), '\', '\\'), '/', '\/') || '/' || replace(replace(coalesce(n."organization_id"::text, ''), '\', '\\'), '/', '\/'), coalesce(date_trunc('month', to_timestamp(n."clock_start_at"), (coalesce((SELECT z."timezone" FROM "organizations" z WHERE z."id" = n."organization_id"), 'UTC'))), 'infinity'), pg_current_xact_id()
          FROM ((SELECT "business_unit_id", "organization_id", "customer_id", "schedule_type", "appointment_start", "arrived_at", "clock_start_at", "notice_deadline_at", "is_open", "arrived_late", "free_minutes_granted", "raw_dwell_minutes", "billable_amount", "driver_pay_amount", "net_margin", "status", "notice_sent_at", "suppressed_by_gate", "waived_amount" FROM keel_old EXCEPT ALL SELECT "business_unit_id", "organization_id", "customer_id", "schedule_type", "appointment_start", "arrived_at", "clock_start_at", "notice_deadline_at", "is_open", "arrived_late", "free_minutes_granted", "raw_dwell_minutes", "billable_amount", "driver_pay_amount", "net_margin", "status", "notice_sent_at", "suppressed_by_gate", "waived_amount" FROM keel_new) UNION ALL (SELECT "business_unit_id", "organization_id", "customer_id", "schedule_type", "appointment_start", "arrived_at", "clock_start_at", "notice_deadline_at", "is_open", "arrived_late", "free_minutes_granted", "raw_dwell_minutes", "billable_amount", "driver_pay_amount", "net_margin", "status", "notice_sent_at", "suppressed_by_gate", "waived_amount" FROM keel_new EXCEPT ALL SELECT "business_unit_id", "organization_id", "customer_id", "schedule_type", "appointment_start", "arrived_at", "clock_start_at", "notice_deadline_at", "is_open", "arrived_late", "free_minutes_granted", "raw_dwell_minutes", "billable_amount", "driver_pay_amount", "net_margin", "status", "notice_sent_at", "suppressed_by_gate", "waived_amount" FROM keel_old)) n
        ON CONFLICT DO NOTHING;
    END IF;
    RETURN NULL;
END
$keel$;
CREATE OR REPLACE TRIGGER "keel_rollup_detention_customer_monthly_insert" AFTER INSERT ON "detention_occurrences" REFERENCING NEW TABLE AS keel_new FOR EACH STATEMENT EXECUTE FUNCTION keel_rollup_detention_customer_monthly();
CREATE OR REPLACE TRIGGER "keel_rollup_detention_customer_monthly_update" AFTER UPDATE ON "detention_occurrences" REFERENCING OLD TABLE AS keel_old NEW TABLE AS keel_new FOR EACH STATEMENT EXECUTE FUNCTION keel_rollup_detention_customer_monthly();
CREATE OR REPLACE TRIGGER "keel_rollup_detention_customer_monthly_delete" AFTER DELETE ON "detention_occurrences" REFERENCING OLD TABLE AS keel_old FOR EACH STATEMENT EXECUTE FUNCTION keel_rollup_detention_customer_monthly();
