WITH marked AS (INSERT INTO keel_rollup_dirty (rollup, tenant_key, bucket, xid) SELECT DISTINCT 'detention_customer_monthly', replace(replace(coalesce(s."business_unit_id"::text, ''), '\', '\\'), '/', '\/') || '/' || replace(replace(coalesce(s."organization_id"::text, ''), '\', '\\'), '/', '\/'), '-infinity'::timestamptz, pg_current_xact_id() FROM "detention_occurrences" s ON CONFLICT DO NOTHING)
INSERT INTO keel_rollup_state (rollup, ready_at) VALUES ('detention_customer_monthly', now()) ON CONFLICT (rollup) DO UPDATE SET ready_at = excluded.ready_at;
